#include <cstdio>
#include <cstring>
#include <string>
#include <vector>
#include <set>
#include <algorithm>

typedef std::pair<size_t, size_t> StringOffset;
struct StringOffsetCompare {
  explicit StringOffsetCompare(const std::vector<uint8_t> &buf) : buf_(&buf) {}
  bool operator()(const StringOffset &a, const StringOffset &b) const {
    auto stra = reinterpret_cast<const char *>(buf_->data() + a.first);
    auto strb = reinterpret_cast<const char *>(buf_->data() + b.first);
    return strncmp(stra, strb, (std::min)(a.second, b.second) + 1) < 0;
  }
  const std::vector<uint8_t> *buf_;
};

int main() {
  std::vector<uint8_t> buf;
  // String 1: "@@\x87\x87\x87b,,4\xff\xff\xff\xff\xff@\xbf@@P@" (20 bytes)
  std::string s1;
  s1 += "@@";
  s1 += (char)0x87; s1 += (char)0x87; s1 += (char)0x87;
  s1 += "b,,4";
  s1 += (char)0xff; s1 += (char)0xff; s1 += (char)0xff; s1 += (char)0xff; s1 += (char)0xff;
  s1 += "@";
  s1 += (char)0xbf;
  s1 += "@@P@";

  // String 2: same prefix + \u0000 + more data
  std::string s2 = s1;
  s2 += (char)0x00;
  s2 += std::string(100, ' ');

  buf.insert(buf.end(), s1.begin(), s1.end());
  buf.push_back(0);
  size_t s1_offset = 0;
  size_t s2_offset = buf.size();
  buf.insert(buf.end(), s2.begin(), s2.end());
  buf.push_back(0);

  printf("s1 len=%zu, s2 len=%zu\n", s1.size(), s2.size());
  printf("s1 offset=%zu, s2 offset=%zu\n", s1_offset, s2_offset);

  StringOffsetCompare cmp(buf);
  StringOffset so1(s1_offset, s1.size());
  StringOffset so2(s2_offset, s2.size());

  bool eq = !cmp(so1, so2) && !cmp(so2, so1);
  printf("Strings considered equal by pool: %s\n", eq ? "YES" : "NO");

  if (eq) {
    printf("BUG: String 2 (len=%zu) will reuse String 1's offset (len=%zu)\n", s2.size(), s1.size());
    printf("When reading String 2, it will read %zu bytes from a %zu-byte string\n", s2.size(), s1.size());
  }

  return 0;
}
EOF
